func FuzzDecodeFraming(f *testing.F) {
	{
		seed := v0.Framing{Variant: v0.DelimiterFraming{Delimiter: "test_1"}}
		w := orc.NewWriter(0)
		if err := seed.EncodeOrc(w); err != nil {
			f.Fatal(err)
		}
		f.Add(w.Bytes())
	}
	{
		seed := v0.Framing{Variant: v0.FixedFraming{Length: 2}}
		w := orc.NewWriter(0)
		if err := seed.EncodeOrc(w); err != nil {
			f.Fatal(err)
		}
		f.Add(w.Bytes())
	}
	{
		seed := v0.Framing{Variant: v0.SyncFraming{
			Sync:              "test_1",
			LengthOffset:      3,
			LengthSize:        4,
			ByteOrder:         library.ByteOrder("little_endian"),
			LengthAdjustment:  6,
			Checksum:          v0.Checksum("none"),
			ChecksumByteOrder: library.ByteOrder("little_endian"),
		}}
		w := orc.NewWriter(0)
		if err := seed.EncodeOrc(w); err != nil {
			f.Fatal(err)
		}
		f.Add(w.Bytes())
	}
	{
		seed := v0.Framing{Variant: v0.CobsFraming{}}
		w := orc.NewWriter(0)
		if err := seed.EncodeOrc(w); err != nil {
			f.Fatal(err)
		}
		f.Add(w.Bytes())
	}
	{
		seed := v0.Framing{Variant: v0.SlipFraming{}}
		w := orc.NewWriter(0)
		if err := seed.EncodeOrc(w); err != nil {
			f.Fatal(err)
		}
		f.Add(w.Bytes())
	}
	f.Fuzz(func(t *testing.T, data []byte) {
		var decoded v0.Framing
		r := orc.NewReader(nil)
		r.ResetBytes(data)
		if err := decoded.DecodeOrc(r); err != nil {
			return
		}
		w1 := orc.NewWriter(len(data))
		if err := decoded.EncodeOrc(w1); err != nil {
			t.Fatalf("encode after successful decode failed: %v", err)
		}
		var redecoded v0.Framing
		r.ResetBytes(w1.Bytes())
		if err := redecoded.DecodeOrc(r); err != nil {
			t.Fatalf("re-decode failed: %v", err)
		}
		if !testutil.DeepEqual(decoded, redecoded) {
			t.Fatal("round-trip mismatch: decoded value changed after an encode/decode cycle")
		}
	})
}

